function h({registerIndicator:u,nulls:f}){u({id:"oa-wins",name:"WINS: Winsorized Mean Moving Average",category:"Statistics",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:20,min:3,max:5e3,step:1},{key:"winPct",type:"number",label:"Winsorize %",default:10,min:0,max:49,step:1,tooltip:"Percentage winsorized from each tail. 0 = SMA"}],plots:[{key:"wins",type:"line",title:"WINS",style:{color:"#ffeb3b",lineWidth:2}}],calc(a,l){const e=Math.max(3,Math.floor(Number(l.period)||20)),m=Math.min(49,Math.max(0,Math.floor(Number(l.winPct)||0)));let n=Math.max(Math.trunc(e*m/100),0);n>=Math.floor(e/2)&&(n=Math.floor((e-1)/2));const c=new Array(a.length).fill(NaN),o=new Array(e);for(let i=e-1;i<a.length;i++){for(let t=0;t<e;t++){const r=a[i-t].close;o[t]=Number.isFinite(r)?r:0}o.sort((t,r)=>t-r);const p=o[n],d=o[e-1-n];for(let t=0;t<n;t++)o[t]=p,o[e-1-t]=d;let s=0;for(let t=0;t<e;t++)s+=o[t];c[i]=s/e}return{wins:f(c)}}})}export{h as default};
